-- Replaces 0001_init.sql's 7-club/3-competition fake seed with the real
-- top-5 European leagues roster, sourced from OpenFootAPI's
-- /v1/competitions and /v1/standings (Starter tier, 2026-10-10).
--
-- clubs.provider_ref keeps the convention from 0001_init.sql: an internal
-- slug id (mirrors packages/mock-data/src/fixtures/clubs.ts), NOT the
-- provider's team id — the provider's team id lives on teams.provider_ref,
-- since that's what match-data.ts's resolveTeamId() looks up by when
-- syncing real matches (see docs/provider-adapter.md's field mapping table).
--
-- This is a replace, not an additive seed: the old fake rows
-- (comp-pl/comp-laliga/comp-ucl, club-ars/club-mci/...) are deleted first.
-- matches/match_events/match_logs rows created against the old fake teams
-- cascade-delete or null out via their FKs; acceptable since this project
-- has no production data yet.

delete from match_events;
delete from match_logs;
delete from matches;
delete from teams;
delete from clubs;
delete from competitions;



